DROP TABLE IF EXISTS `producto_existencias`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `producto_existencias` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `producto_id` int(11) NOT NULL,
  `sucursal` varchar(100) NOT NULL,
  `ubicacion` varchar(120) DEFAULT NULL,
  `existencia` int(11) NOT NULL DEFAULT 0,
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_producto_sucursal_ubicacion` (`producto_id`,`sucursal`,`ubicacion`),
  CONSTRAINT `fk_producto_existencias_producto` FOREIGN KEY (`producto_id`) REFERENCES `productos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14278 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
